import { useEffect, useState } from "react";

export default function AdminFeedback() {
  const [feedbacks, setFeedbacks] = useState([]);

  const load = async () => {
    const res = await fetch("http://127.0.0.1:8000/api/admin/feedbacks/");
    const data = await res.json();
    setFeedbacks(data);
  };

  useEffect(() => {
    load();
  }, []);

  return (
    <div>
      <h3>User Feedback</h3>

      {feedbacks.length === 0 && <p>No feedback yet.</p>}

      {feedbacks.map(f => (
        <div key={f.id} className="card" style={{ marginBottom: 10 }}>
          <b>Order:</b> #{f.order_id}<br/>
          <b>User:</b> {f.user}<br/>
          <b>Rating:</b> {f.rating} ⭐<br/>
          <b>Comment:</b> {f.comment || "—"}<br/>
          <small>{new Date(f.created_at).toLocaleString()}</small>
        </div>
      ))}
    </div>
  );
}
